// OT3-11: the quest/phase scanner (tools/scan-quests.mjs) over synthetic TES3 files written here.
// No Bethesda data: every record below is generated by the tiny writer in this file.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const TOOL = join(dirname(fileURLToPath(import.meta.url)), '..', 'tools', 'scan-quests.mjs');

type Sub = [string, Buffer];
const z = (s: string) => Buffer.from(s + '\0', 'latin1');
const raw = (s: string) => Buffer.from(s, 'latin1');
const i32 = (...v: number[]) => { const b = Buffer.alloc(4 * v.length); v.forEach((x, i) => b.writeInt32LE(x, i * 4)); return b; };
const u8 = (v: number) => Buffer.from([v]);

function record(type: string, subs: Sub[], flags = 0): Buffer {
  const body = Buffer.concat(subs.map(([n, d]) => { const h = Buffer.alloc(8); h.write(n, 0, 'latin1'); h.writeUInt32LE(d.length, 4); return Buffer.concat([h, d]); }));
  const h = Buffer.alloc(16);
  h.write(type, 0, 'latin1'); h.writeUInt32LE(body.length, 4); h.writeUInt32LE(flags, 12);
  return Buffer.concat([h, body]);
}
const header = () => record('TES3', [['HEDR', Buffer.alloc(300)]]);
function scpt(id: string, text: string): Buffer {
  const schd = Buffer.alloc(52); schd.write(id, 0, 'latin1');
  return record('SCPT', [['SCHD', schd], ['SCTX', raw(text)]]);
}
const dial = (id: string, type: number) => record('DIAL', [['NAME', z(id)], ['DATA', u8(type)]]);
function info(o: { id: string; index?: number; text?: string; result?: string; actor?: string; faction?: string; rank?: number; name?: boolean; finished?: boolean; conds?: [string, number][] }): Buffer {
  const data = Buffer.alloc(12); data.writeInt32LE(o.index ?? 0, 4); data.writeInt8(o.rank ?? -1, 8);
  const subs: Sub[] = [['INAM', z(o.id)], ['PNAM', z('')], ['NNAM', z('')], ['DATA', data]];
  if (o.actor) subs.push(['ONAM', z(o.actor)]);
  if (o.faction) subs.push(['FNAM', z(o.faction)]);
  if (o.text) subs.push(['NAME', raw(o.text)]);
  for (const [c, v] of o.conds ?? []) subs.push(['SCVR', raw(c)], ['INTV', i32(v)]);
  if (o.result) subs.push(['BNAM', raw(o.result)]);
  if (o.name) subs.push(['QSTN', u8(1)]);
  if (o.finished) subs.push(['QSTF', u8(1)]);
  return record('INFO', subs);
}
function cell(name: string, refs: string[], interior = true, x = 0, y = 0): Buffer {
  const subs: Sub[] = [['NAME', z(name)], ['DATA', i32(interior ? 1 : 0, x, y)]];
  refs.forEach((r, i) => subs.push(['FRMR', i32(i + 1)], ['NAME', z(r)], ['DATA', Buffer.alloc(24)]));
  return record('CELL', subs);
}

function run(files: Buffer[][]) {
  const dir = mkdtempSync(join(tmpdir(), 'questscan-'));
  try {
    const paths = files.map((recs, i) => { const p = join(dir, `f${i}.esm`); writeFileSync(p, Buffer.concat([header(), ...recs])); return p; });
    const out = join(dir, 'out');
    const r = spawnSync(process.execPath, [TOOL, '--out-dir', out, ...paths], { encoding: 'utf8' });
    assert.equal(r.status, 0, r.stderr + r.stdout);
    const j = (f: string) => JSON.parse(readFileSync(join(out, f), 'utf8'));
    return { stdout: r.stdout, cells: j('phase-cells.json'), quests: j('phase-quests.json'), stages: j('phase-stages.json'), classes: j('script-classes.json'), report: j('phase-scan-report.json') };
  } finally { rmSync(dir, { recursive: true, force: true }); }
}

const base = (): Buffer[] => [
  dial('q_rescue', 4),
  info({ id: 'n', name: true, text: 'Rescue the Miner' }),
  info({ id: 's10', index: 10, text: 'I agreed to help.' }),
  info({ id: 's20', index: 20, text: 'Done, the miner is free.', finished: true }),
  info({ id: 's30', index: 30, text: 'I left him there.', finished: true }),
  dial('mine', 0),
  info({ id: 't1', actor: 'foreman', faction: 'fighters guild', rank: 2, conds: [['04JX3q_intro', 50]], result: 'Journal "q_rescue" 10\nStartScript ScriptA' }),
  scpt('scripta', 'Begin ScriptA\nStartScript "ScriptB"\nStopScript ScriptA\nEnd'),
  scpt('scriptb', 'Begin ScriptB\n"miner_guard"->Disable ; gone\nPlaceItemCell "gold_001" "Abandoned Mine" 0 0 0 0\nEnd'),
  cell('Abandoned Mine', ['miner_guard', 'crate_01']),
  cell('', ['other_rock'], false, 3, -4),
];

test('dialogue -> StartScript A -> StartScript B -> Disable is attributed to the stage the dialogue sets', () => {
  const t = run([base()]);
  const eff = t.stages['q_rescue:10'].effects;
  const dis = eff.find((e: { op: string }) => e.op === 'disable');
  assert.ok(dis, JSON.stringify(eff));
  assert.equal(dis.ref, 'miner_guard');
  assert.deepEqual(dis.via, ['scripta', 'scriptb']);
  assert.equal(dis.source, 'info:mine:t1');
  assert.ok(eff.some((e: { op: string; args: string[] }) => e.op === 'placeitemcell' && e.args[0] === 'gold_001'));
  assert.ok(eff.some((e: { op: string }) => e.op === 'stopscript'));
  // The stage's own Journal call is not listed as its effect.
  assert.ok(!eff.some((e: { op: string; via?: string[] }) => e.op === 'journal' && !e.via));
  assert.deepEqual(t.cells['abandoned mine'].phaseKeys, ['q_rescue:10']);
  assert.equal(t.cells['3,-4'], undefined);
  assert.equal(t.report.startScriptCalls, 2);
  assert.equal(t.report.resolved, 2);
  assert.deepEqual(t.report.unresolved, []);
});

test('quest table: kind, eligibility and branches', () => {
  const q = run([base()]).quests.q_rescue;
  assert.equal(q.name, 'Rescue the Miner');
  assert.equal(q.kind, 'faction');
  assert.deepEqual(q.stages, [10, 20, 30]);
  assert.deepEqual(q.branches, [20, 30]);
  assert.deepEqual(q.eligibility.givers, ['foreman']);
  assert.deepEqual(q.eligibility.factions, ['fighters guild']);
  assert.equal(q.eligibility.minRank, 2);
  assert.deepEqual(q.eligibility.requires, ['q_intro>=50']);
});

test('script classes: global, startup, local, started/stopped by', () => {
  const recs = [...base(), record('SSCR', [['DATA', z('1')], ['NAME', z('Main')]]), scpt('main', 'Begin Main\nEnd'),
    scpt('doorscript', 'Begin DoorScript\nEnd'), record('DOOR', [['NAME', z('mine_door')], ['SCRI', z('DoorScript')]])];
  const c = run([recs]).classes;
  assert.deepEqual(c.scripta.classes, ['global']);
  assert.deepEqual(c.scripta.startedBy, ['info:mine:t1']);
  assert.deepEqual(c.scripta.stoppedBy, ['script:scripta']);
  assert.deepEqual(c.scriptb.startedBy, ['script:scripta']);
  assert.deepEqual(c.main.classes, ['startup']);
  assert.deepEqual(c.doorscript.classes, ['local']);
  assert.deepEqual(c.doorscript.attachedTo, ['mine_door']);
});

test('GetJournalIndex conditions attribute the enclosed effects; same-block Journal calls do too', () => {
  const recs = [...base(), scpt('watcher', [
    'Begin Watcher',
    'if ( GetJournalIndex "q_rescue" >= 20 )',
    '  "crate_01"->Enable',
    'elseif ( GetJournalIndex "q_rescue" == 30 )',
    '  "crate_01"->SetPos x 5',
    'else',
    '  Journal "q_rescue" 30',
    '  "other_rock"->Disable',
    'endif',
    'End'].join('\n'))];
  const t = run([recs]);
  assert.ok(t.stages['q_rescue:20'].effects.some((e: { op: string; ref?: string }) => e.op === 'enable' && e.ref === 'crate_01'));
  assert.ok(!t.stages['q_rescue:20'].effects.some((e: { op: string }) => e.op === 'setpos'));
  assert.ok(t.stages['q_rescue:30'].effects.some((e: { op: string }) => e.op === 'setpos'));
  assert.ok(t.stages['q_rescue:30'].effects.some((e: { op: string; ref?: string }) => e.op === 'disable' && e.ref === 'other_rock'));
  assert.deepEqual(t.cells['3,-4'].phaseKeys, ['q_rescue:30']);
  assert.deepEqual(t.cells['abandoned mine'].phaseKeys, ['q_rescue:10', 'q_rescue:20', 'q_rescue:30']);
});

test('cycles and unresolved targets are reported, not fatal', () => {
  const recs = [
    dial('q_loop', 4), info({ id: 's1', index: 1, text: 'start' }),
    dial('t', 0), info({ id: 'a', result: 'Journal q_loop 1\nStartScript CycA\nStartScript NoSuchScript' }),
    scpt('cyca', 'Begin CycA\nStartScript CycB\n"x"->Disable\nEnd'),
    scpt('cycb', 'Begin CycB\nStartScript CycA\n"y"->Enable\nEnd'),
  ];
  const t = run([recs]);
  assert.deepEqual(t.report.unresolved, [{ target: 'nosuchscript', from: 'info:t:a', line: 3 }]);
  assert.equal(t.report.cycles.length, 1);
  assert.deepEqual(t.report.cycles[0], ['cyca', 'cycb', 'cyca']);
  const ops = t.stages['q_loop:1'].effects.map((e: { op: string; ref?: string }) => `${e.op}:${e.ref ?? ''}`);
  assert.ok(ops.includes('disable:x') && ops.includes('enable:y'), ops.join(','));
  assert.match(t.stdout, /unresolved: nosuchscript/);
  assert.match(t.stdout, /cycle: cyca -> cycb -> cyca/);
});

test('a later file in the load order replaces a script and adds a stage', () => {
  const t = run([base(), [
    scpt('scriptb', 'Begin ScriptB\n"crate_01"->Disable\nEnd'),
    dial('q_rescue', 4), info({ id: 's40', index: 40, text: 'A new ending.', finished: true }),
  ]]);
  const eff = t.stages['q_rescue:10'].effects;
  assert.ok(eff.some((e: { ref?: string }) => e.ref === 'crate_01'));
  assert.ok(!eff.some((e: { ref?: string }) => e.ref === 'miner_guard'));
  assert.deepEqual(t.quests.q_rescue.branches, [20, 30, 40]);
});
